/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK updateVoices(s32);                         /* extern */
extern s32 gAudioUpdateRate;
extern s32 gAudioTickStep;
extern s32 gAudioOutputRate;

/* Recomputes the per-update tick step from the update rate and output rate, then runs the voice update. */ void updateAudioTickStep(void) {
    if (gAudioUpdateRate != 0) {
        gAudioTickStep = ((s32) (gAudioUpdateRate * 0x7D00) / (s32) gAudioOutputRate) * 8;
        updateVoices(gAudioUpdateRate);
    }
}
